data.yaml:
# yaml-language-server: $schema=../../packages/core/schema/template.schema.json
# Retake starter template "editorial": warm and premium — the reference look for product videos
# (docs/reference/look.md). Instrument Serif display over Inter body, accent on a warm paper background.
# Placeholder brand: "Atelier" (logo.svg, wordmark.svg) — replace it with yours (see README.md).
version: 1
name: editorial

colors:
  accent: "#8a2332"   # deep wine: kicker, rules, clock hour hand, cursor ripple
  text: "#1f1413"     # warm ink: titles and caption lines
  muted: "#6b605d"    # taglines, url
  paper: "#f3eee8"    # warm paper; text colour on the dark interstitial

fonts:
  display: fonts/InstrumentSerif-Regular.ttf
  body: [fonts/Inter-Regular.ttf, fonts/Inter-SemiBold.ttf, fonts/Inter-Bold.ttf]

logo: logo.svg
wordmark: wordmark.svg
brand: {name: Atelier, url: example.com}       # placeholder brand (fictional)

background: {type: radial, from: "#f8f4ef", to: "#ebe4dc"}

frame: {style: card, width: 1560, radius: 18, shadow: soft}

captions:
  position: below
  kicker: {font: body, weight: 600, size: 15, uppercase: true, color: accent, letter_spacing: 0.14}
  line: {font: display, size: 38, color: text}

intro: {duration: 3.2, layout: logo-kicker-title}
outro: {duration: 3.0, layout: logo-wordmark-tagline-url, url: example.com}
interstitial: {style: dark-clock, duration: 2.6}
transitions: {between_scenes: crossfade, duration: 0.35}

cursor: {style: arrow-dark, ripple_color: "rgba(138, 35, 50, 0.45)"}

motion: {default_zoom: none, max_zoom: 1.4, zoom_ease: [0.45, 0, 0.2, 1]}
style_bias: real

brandmark: {position: bottom-right, size: 30}

# Default component per kind (docs/DESIGN-phase2.md §1.4), consistent with the legacy fields above:
# the reference look — stacked intro and outro, clock interstitial, card layout, captions below, crossfade.
components:
  intro: studio/intro-stack
  outro: studio/outro-stack
  interstitial: studio/interstitial-clock
  card: studio/card-title
  layout: {id: studio/layout-card, params: {width: 1560, radius: 18, shadow: soft}}
  caption: studio/caption-below
  overlay: studio/overlay-callout
  transition: {id: studio/transition-crossfade, params: {duration: 0.35}}

